cat > testing/mocks/handlers/teams.ts <<'EOF'
import { HttpResponse, http } from 'msw';

import { env } from '@/config/env';

import { db, persistDb } from '../db';
import { networkDelay, requireAuth } from '../utils';

type CreateTeamBody = {
  name: string;
  description: string;
};

export const teamsHandlers = [
  http.get(`${env.API_URL}/teams`, async () => {
    await networkDelay();

    try {
      const result = db.team.getAll();
      return HttpResponse.json({ data: result });
    } catch (error: any) {
      return HttpResponse.json(
        { message: error?.message || 'Server Error' },
        { status: 500 },
      );
    }
  }),

  http.post(`${env.API_URL}/teams`, async ({ request, cookies }) => {
    await networkDelay();

    try {
      const { user, error } = requireAuth(cookies);
      if (error) {
        return HttpResponse.json({ message: error }, { status: 401 });
      }
      if (user?.role !== 'ADMIN') {
        return HttpResponse.json({ message: 'Forbidden' }, { status: 403 });
      }

      const data = (await request.json()) as Partial<CreateTeamBody>;
      const name = data?.name?.trim();
      const description = data?.description?.trim();
      if (!name || !description) {
        return HttpResponse.json(
          { message: 'Name and description are required' },
          { status: 400 },
        );
      }

      const result = db.team.create({ name, description });
      await persistDb('team');
      return HttpResponse.json(result);
    } catch (error: any) {
      return HttpResponse.json(
        { message: error?.message || 'Server Error' },
        { status: 500 },
      );
    }
  }),
];
EOF
